<script setup lang="ts">
import { ref } from 'vue'
import type { Slide,Theme } from '@/types/aippt'
import SlideThumbnail from './SlideThumbnail.vue'
const props=defineProps<{slides:Slide[];theme:Theme;selected:string;disabled?:boolean}>(),emit=defineEmits<{select:[id:string];order:[ids:string[]];insert:[];duplicate:[];remove:[]}>();const dragged=ref('')
function drop(to:string){const ids=props.slides.map(s=>s.id),from=ids.indexOf(dragged.value),at=ids.indexOf(to);dragged.value='';if(from<0||from===at)return;const [id]=ids.splice(from,1);ids.splice(at,0,id);emit('order',ids)}
function move(id:string,d:number){const ids=props.slides.map(s=>s.id),at=ids.indexOf(id);if(at+d<0||at+d>=ids.length)return;[ids[at],ids[at+d]]=[ids[at+d],ids[at]];emit('order',ids)}
</script>
<template><aside class="filmstrip" aria-label="页面列表"><div class="film-actions"><el-button size="small" :disabled="disabled||slides.length>=40" @click="emit('insert')">插入页</el-button><el-button size="small" :disabled="disabled||!selected||slides.length>=40" @click="emit('duplicate')">复制</el-button><el-button size="small" type="danger" :disabled="disabled||slides.length<=1" @click="emit('remove')">删除</el-button></div><article v-for="(slide,index) in slides" :key="slide.id" :class="['film',{active:slide.id===selected}]" :draggable="!disabled" @dragstart="dragged=slide.id" @dragover.prevent @drop.prevent="!disabled&&drop(slide.id)"><button :aria-label="'选择第'+(index+1)+'页 '+slide.title" :aria-pressed="slide.id===selected" @click="emit('select',slide.id)"><SlideThumbnail :slide="slide" :theme="theme" :index="index"/><span>{{index+1}}. {{slide.blocks.find(b=>b.type==='text'&&b.slot_id==='title')?.type==='text'?(slide.blocks.find(b=>b.type==='text'&&b.slot_id==='title') as any).text:slide.title}}</span></button><div class="film-order"><el-button size="small" link :disabled="disabled||index===0" @click="move(slide.id,-1)">上移</el-button><el-button size="small" link :disabled="disabled||index===slides.length-1" @click="move(slide.id,1)">下移</el-button><el-tag v-if="slide.status==='failed'" size="small" type="danger">失败</el-tag></div></article></aside></template>
<style scoped>.filmstrip{overflow:auto;max-height:calc(100vh - 260px);min-width:0;padding:10px;background:#fff;border:1px solid #ebeef5;border-radius:8px}.film-actions{display:flex;gap:4px;flex-wrap:wrap;margin-bottom:14px}.film-actions .el-button{margin:0}.film{margin-bottom:12px;padding:5px;border:2px solid transparent;border-radius:6px}.film.active{border-color:#409eff}.film>button{background:transparent;border:0;width:100%;padding:0;text-align:left;cursor:pointer}.film span{display:block;margin-top:7px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;font-size:12px}.film-order{display:flex;align-items:center;gap:8px;margin-top:5px}</style>
